void Solver::rephase() {
    rephases = 0;
    threshold = (int)(threshold * 0.85);
    rephase_limit += 10000;
    // Flip saved phases for all variables to escape local optima
    for (int i = 1; i <= vars; i++) {
        if (local_best[i] != 0)
            saved[i] = local_best[i];
        else
            saved[i] = rand() % 2 ? 1 : -1;
    }
}
